  delete from public.ingresos_egresos where lote_importacion in (select distinct lote from _imp);
  insert into public.proveedores (nombre) select distinct on (lower(prov)) prov from _imp where trim(prov) <> '' on conflict (lower(nombre)) do nothing;
  insert into public.ingresos_egresos (fecha, proveedor_id, concepto, factura_numero, monto, forma, estado_pago, medio_pago, origen, usuario_id, observaciones, lote_importacion)
  select i.fecha::date, (select p.id from public.proveedores p where lower(p.nombre) = lower(i.prov)), i.conc, nullif(i.fac, ''), i.monto,
    case i.f when 'OI' then 'otros_ingresos' when 'DP' then 'deuda_proveedores' when 'OD' then 'otras_deudas' when 'AH' then 'ahorro' when 'AB' then 'acred_banco' when 'EB' then 'egreso_banco' else 'egreso_efectivo' end,
    'pagado'::estado_pago_tipo,
    case i.f when 'EB' then 'banco' when 'EE' then 'efectivo' else null end,
    'manual', (select id from public.usuarios where rol = 'admin' order by created_at limit 1), 'Importado del Excel ' || i.lote, i.lote
  from _imp i;
end
$$;
